    savedDeals.add(dealTitle);
    button.classList.add("is-saved");
    button.textContent = "Saved offer";
    button.setAttribute("aria-pressed", "true");
    button.setAttribute("aria-label", `Saved offer: ${dealTitle}`);
    announce(`${dealTitle} saved.`);
  }

  savedCount.textContent = `${savedDeals.size} saved offer${savedDeals.size === 1 ? "" : "s"}`;
}

filterButtons.forEach((button) => {
  button.addEventListener("click", () => {
    const selectedFilter = button.dataset.filter;

    filterButtons.forEach((item) => {
      const isCurrent = item === button;
      item.classList.toggle("is-active", isCurrent);
      item.setAttribute("aria-pressed", String(isCurrent));
    });

    renderProducts(selectedFilter);

    const visibleCount =
