    announce(`Showing ${visibleCount} ${selectedFilter === "all" ? "featured" : selectedFilter} items.`);
  });
});

document.addEventListener("click", (event) => {
  const target = event.target;

  if (!(target instanceof HTMLElement)) {
    return;
