           <article class="product-card">
             <div class="product-card-top">
               <span class="product-kicker">${product.label}</span>
               <span class="product-price">${product.price}</span>
             </div>
             <div>
               <a class="product-link" href="${product.href}">
                 <h3>${product.name}</h3>
               </a>
               <p class="product-copy">${product.description}</p>
             </div>
             <div class="product-actions">
               <button
                 type="button"
                 class="product-action"
                 data-product-name="${product.name}"
                 aria-label="Add to bag: ${product.name}"
               >
                 Add to bag
               </button>
               <a class="button button-secondary" href="${product.href}">View details</a>
             </div>
           </article>
         </li>
       `,
     )
     .join("");
 }

 function renderDeals() {
   dealGrid.innerHTML = deals
     .map(
       (deal, index) => `
         <li>
           <article class="deal-card">
             <div class="deal-meta">
               <span class="deal-tag">${deal.badge}</span>
               <span class="deal-kicker">Deal ${index + 1}</span>
             </div>
             <a class="deal-link" href="${deal.href}">
               <h3>${deal.title}</h3>
             </a>
             <p class="deal-copy">${deal.description}</p>
             <div class="deal-actions">
               <button
                 type="button"
                 class="deal-action"
                 data-deal-title="${deal.title}"
                 aria-pressed="false"
                 aria-label="Save offer: ${deal.title}"
               >
                 Save offer
               </button>
               <a class="button button-secondary" href="${deal.href}">Shop offer</a>
             </div>
           </article>
         </li>
       `,
     )
     .join("");
 }

 function updateBag(productName) {
   bagItems += 1;
   cartCount.textContent = String(bagItems);
   cartCount.setAttribute(
     "aria-label",
     `${bagItems} item${bagItems === 1 ? "" : "s"} in bag`,
   );
   announce(`${productName} added to bag. ${bagItems} item${bagItems === 1 ? "" : "s"} in bag.`);
 }

 function updateSavedOffers(button, dealTitle) {
   if (savedDeals.has(dealTitle)) {
     savedDeals.delete(dealTitle);
     button.classList.remove("is-saved");
     button.textContent = "Save offer";
     button.setAttribute("aria-pressed", "false");
     button.setAttribute("aria-label", `Save offer: ${dealTitle}`);
     announce(`${dealTitle} removed from saved offers.`);
   } else {
     savedDeals.add(dealTitle);
     button.classList.add("is-saved");
     button.textContent = "Saved offer";
     button.setAttribute("aria-pressed", "true");
     button.setAttribute("aria-label", `Saved offer: ${dealTitle}`);
     announce(`${dealTitle} saved.`);
   }

