   const target = event.target;

   if (!(target instanceof HTMLElement)) {
     return;
   }

   if (target.matches(".product-action")) {
     updateBag(target.dataset.productName || "Item");
   }

   if (target.matches(".deal-action")) {
     updateSavedOffers(target, target.dataset.dealTitle || "Offer");
   }
 });

