    <p class="sr-only" id="announcement" role="status" aria-atomic="true"></p>

    <script>
      const products = [
        {
          name: "Meridian Wool Coat",
          category: "fashion",
          label: "Tailoring",
          price: "$248",
          description: "A structured overcoat with soft brushed texture and sharp lapels.",
          href: "#featured",
        },
        {
          name: "Halo Leather Tote",
          category: "fashion",
          label: "Accessories",
          price: "$198",
          description: "Smooth leather, minimal hardware, and room for every daily essential.",
          href: "#featured",
        },
        {
          name: "Lumen Table Lamp",
          category: "home",
          label: "Home",
          price: "$126",
          description: "A smoked-glass lamp that adds warm contrast to deep, moody interiors.",
          href: "#featured",
        },
        {
          name: "Noir Throw Blanket",
          category: "home",
          label: "Home",
          price: "$84",
          description: "Heavy-knit comfort designed for reading corners and late-night movies.",
          href: "#featured",
        },
        {
          name: "Velvet Bloom Serum",
          category: "beauty",
          label: "Beauty",
          price: "$46",
          description: "A glow-boosting serum that layers easily under night creams.",
          href: "#featured",
        },
        {
          name: "Afterlight Candle Trio",
          category: "beauty",
          label: "Wellness",
          price: "$58",
          description: "Three low-smoke scents with cedar, bergamot, and amber notes.",
          href: "#featured",
        },
      ];

      const deals = [
        {
          title: "20% off outer layers",
          description: "Use code NIGHT20 on coats, knits, and weather-ready accessories.",
          badge: "Ends tonight",
          href: "#deals",
        },
        {
          title: "Buy two candles, save $18",
          description: "Mix any signature candle scents and refresh your whole space.",
          badge: "Bundle offer",
          href: "#deals",
        },
        {
          title: "Free express delivery",
          description: "Applied automatically to home accents and decor orders over $180.",
          badge: "48 hours",
          href: "#deals",
        },
      ];

      const featuredGrid = document.querySelector("#featured-grid");
      const dealGrid = document.querySelector("#deal-grid");
      const filterInputs = document.querySelectorAll('input[name="featured-filter"]');
      const cartCount = document.querySelector("#cart-count");
      const savedCount = document.querySelector("#saved-count");
      const announcement = document.querySelector("#announcement");

      let bagItems = 0;
      let announcementTimer = 0;
      const savedDeals = new Set();

      function announce(message) {
        window.clearTimeout(announcementTimer);
        announcement.textContent = "";
        announcementTimer = window.setTimeout(() => {
          announcement.textContent = message;
        }, 50);
      }

      function renderProducts(filter) {
        const visibleProducts =
          filter === "all"
            ? products
            : products.filter((product) => product.category === filter);

        featuredGrid.innerHTML = visibleProducts
          .map(
            (product) => `
              <li>
                <article class="product-card">
                  <div class="product-card-top">
                    <span class="product-kicker">${product.label}</span>
                    <span class="product-price">${product.price}</span>
                  </div>
                  <div>
                    <a class="product-link" href="${product.href}">
                      <h3>${product.name}</h3>
                    </a>
                    <p class="product-copy">${product.description}</p>
                  </div>
                  <div class="product-actions">
                    <button
                      type="button"
                      class="product-action"
                      data-product-name="${product.name}"
                      aria-label="Add to bag: ${product.name}"
                    >
                      Add to bag
                    </button>
                    <a class="button button-secondary" href="${product.href}">View details</a>
                  </div>
                </article>
              </li>
            `,
          )
          .join("");
      }

      function renderDeals() {
        dealGrid.innerHTML = deals
          .map(
            (deal, index) => `
              <li>
                <article class="deal-card">
                  <div class="deal-meta">
                    <span class="deal-tag">${deal.badge}</span>
                    <span class="deal-kicker">Deal ${index + 1}</span>
                  </div>
                  <a class="deal-link" href="${deal.href}">
                    <h3>${deal.title}</h3>
                  </a>
                  <p class="deal-copy">${deal.description}</p>
                  <div class="deal-actions">
                    <button
                      type="button"
                      class="deal-action"
                      data-deal-title="${deal.title}"
                      aria-pressed="false"
                      aria-label="Save offer: ${deal.title}"
                    >
                      Save offer
                    </button>
                    <a class="button button-secondary" href="${deal.href}">Shop offer</a>
                  </div>
                </article>
              </li>
            `,
          )
          .join("");
      }

      function updateBag(productName) {
        bagItems += 1;
        cartCount.textContent = String(bagItems);
        announce(`${productName} added to bag. ${bagItems} item${bagItems === 1 ? "" : "s"} in bag.`);
      }

      function updateSavedOffers(button, dealTitle) {
        if (savedDeals.has(dealTitle)) {
          savedDeals.delete(dealTitle);
          button.classList.remove("is-saved");
          button.textContent = "Save offer";
          button.setAttribute("aria-pressed", "false");
          button.setAttribute("aria-label", `Save offer: ${dealTitle}`);
          announce(`${dealTitle} removed from saved offers.`);
        } else {
          savedDeals.add(dealTitle);
          button.classList.add("is-saved");
          button.textContent = "Saved offer";
          button.setAttribute("aria-pressed", "true");
          button.setAttribute("aria-label", `Saved offer: ${dealTitle}`);
          announce(`${dealTitle} saved.`);
        }

        savedCount.textContent = `Saved offers: ${savedDeals.size}`;
      }

      filterInputs.forEach((input) => {
        input.addEventListener("change", () => {
          if (!input.checked) {
            return;
          }

          renderProducts(input.value);

          const visibleCount =
            input.value === "all"
              ? products.length
              : products.filter((product) => product.category === input.value).length;

          announce(`Showing ${visibleCount} ${input.value === "all" ? "featured" : input.value} items.`);
        });
      });

      document.addEventListener("click", (event) => {
        const target = event.target;

        if (!(target instanceof HTMLElement)) {
          return;
        }

        if (target.matches(".product-action")) {
          updateBag(target.dataset.productName || "Item");
        }

        if (target.matches(".deal-action")) {
          updateSavedOffers(target, target.dataset.dealTitle || "Offer");
        }
      });

      renderProducts("all");
      renderDeals();
    </script>
  </body>
</html>
